let cachedRows = [];

function removeRow(row) {
  row.remove();
}

function renderRow(data) {
  const row = document.createElement('tr');
  row.textContent = data.label;
  row.addEventListener('click', () => console.log(data.id));
  cachedRows.push(row);
  document.querySelector('tbody').appendChild(row);
  return row;
}

